('APX-S-4725-3', 'APX-C-4725', 3, null, null, null, null, 1163, 441, 'The environment should feel like a real premium sports broadcast: bright even stadium floodlights, crowd depth, huge overhead jumbotron, subtle live-broadcast polish, clean digital overlays, a LIVE badge, and Korean-style sports broadcast…', null, null, null, null, 'stadium', null),
('APX-S-4725-4', 'APX-C-4725', 4, null, null, null, 'Keep the motion smooth and believable. Keep the pacing realistic for a 5–8 second clip. The sequence should feel like a real live TV capture, not a staged skit. Avoid exaggerated comedy acting. Avoid political symbolism, propaganda framing, influencer posing, uncanny deepfake energy, broken hands, distorted phone screens, or glitchy crowd motion. Keep Yuki’s face 100% consistent with her real face.', null, null, 'Keep the motion smooth and believable. Keep the pacing for a 5–8 second clip. The sequence should feel like a real live TV capture, not a staged skit. Avoid exaggerated comedy acting.', null, null, null, null, null, 'comedic'),
